"""Regenerate internal/bm25/logtab.go: the __log_data table of the glibc libm CPython calls.

Run: python3 -I internal/bm25/testdata/gen_logtab.py [path/to/libm.so.6]

CPython's math.log is glibc's log; on x86-64 with FMA that is __log_fma, the Arm
optimized-routines algorithm (MIT OR Apache-2.0 WITH LLVM-exception) over a 128-entry
table. Go's math.Log differs from it by one ulp on ~1.4 % of BM25 idf inputs, so the
Go port (log.go) uses the very table, read here from the shared library: the struct
starts with ln2hi, ln2lo; then poly[5], poly1[11] and tab[128] of {invc, logc}.
"""
import os
import struct
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
LIBM = sys.argv[1] if len(sys.argv) > 1 else "/lib/x86_64-linux-gnu/libm.so.6"
LN2HI, LN2LO = float.fromhex("0x1.62e42fefa3800p-1"), float.fromhex("0x1.ef35793c76730p-45")
POLY0 = float.fromhex("-0x1.0000000000001p-1")    # first coefficient of __log_data.poly
POLY1_0 = -0.5                                     # first coefficient of __log_data.poly1


def main():
    blob = open(LIBM, "rb").read()
    head = struct.pack("<ddd", LN2HI, LN2LO, POLY0)
    at = blob.find(head)
    if at < 0 or blob.find(head, at + 1) >= 0:
        sys.exit("gen_logtab.py: __log_data not found exactly once in " + LIBM)
    n = 2 + 5 + 11 + 2 * 128
    v = struct.unpack("<%dd" % n, blob[at:at + 8 * n])
    if v[7] != POLY1_0:
        sys.exit("gen_logtab.py: unexpected __log_data layout in " + LIBM)
    h = lambda x: x.hex()
    out = [
        "// Code generated by testdata/gen_logtab.py from glibc's __log_data; DO NOT EDIT.",
        "",
        "package bm25",
        "",
        "const (",
        "\tlogLn2hi = %s" % h(v[0]),
        "\tlogLn2lo = %s" % h(v[1]),
        ")",
        "",
        "var logPoly = [5]float64{%s}" % ", ".join(map(h, v[2:7])),
        "",
        "var logPoly1 = [11]float64{",
    ]
    out += ["\t%s," % h(x) for x in v[7:18]]
    out += ["}", "", "// logTab[i] = {invc, logc}.", "var logTab = [128][2]float64{"]
    out += ["\t{%s, %s}," % (h(v[18 + 2 * i]), h(v[19 + 2 * i])) for i in range(128)]
    out += ["}", ""]
    with open(os.path.join(HERE, "..", "logtab.go"), "w", encoding="utf-8", newline="\n") as fh:
        fh.write("\n".join(out))


if __name__ == "__main__":
    main()
